def get_neighbors(r, c, rows, cols):
    """Get all neighbors including diagonals"""
    neighbors = []
    for dr in range(-1, 2):
        for dc in range(-1, 2):
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                neighbors.append((nr, nc))
    return neighbors

def get_connected_components(grid, dim=6):
    """Get all positions of value dim, grouped into connected components"""
    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == dim and (r, c) not in visited:
                component = []
                stack = [(r, c)]
                while stack:
                    curr_r, curr_c = stack.pop()
                    if (curr_r, curr_c) in visited:
                        continue
                    visited.add((curr_r, curr_c))
                    component.append((curr_r, curr_c))
                    for nr, nc in get_neighbors(curr_r, curr_c, rows, cols):
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == dim and (nr, nc) not in visited:
                                stack.append((nr, nc))
                components.append(component)

    return components

